import {angleDiff} from './engine.js';
export const VERSION='0.8.0';
export const LABELS={CENTER:'중앙',LEFT:'왼쪽',RIGHT:'오른쪽',UP:'위',DOWN:'아래',UP_LEFT:'좌상',UP_RIGHT:'우상',DOWN_LEFT:'좌하',DOWN_RIGHT:'우하',INSIDE:'화면 안',OUTSIDE:'화면 밖',UNKNOWN:'측정 실패',UNCLEAR:'판단 불가'};
export const DIRECTIONS=['CENTER','LEFT','RIGHT','UP','DOWN','UP_LEFT','UP_RIGHT','DOWN_LEFT','DOWN_RIGHT'];
export const HEADS=['CENTER','LEFT','RIGHT','UP','DOWN','TILT_LEFT','TILT_RIGHT'];
Object.assign(LABELS,{TILT_LEFT:'좌 기울임',TILT_RIGHT:'우 기울임'});
export const SETTINGS={bin:.5,hold:.15,ear:.20,yaw:20,pitch:15,roll:15,directionLow:.35,directionHigh:.65};
export const CAL_POINTS=[[.5,.5],[.12,.12],[.5,.12],[.88,.12],[.88,.5],[.88,.88],[.5,.88],[.12,.88],[.12,.5]];
export function fitScreen(points){
 if(points.length!==9)throw Error('9개 보정 표적을 모두 수집해야 합니다.');
 const avg=k=>points.reduce((s,p)=>s+p[k],0)/points.length;const ix=avg('irisX'),iy=avg('irisY');
 let xx=0,yy=0,xy=0,xt=0,yt=0,xu=0,yu=0;const tx=avg('x'),ty=avg('y');
 for(const p of points){const a=p.irisX-ix,b=p.irisY-iy;xx+=a*a;yy+=b*b;xy+=a*b;xt+=a*(p.x-tx);yt+=b*(p.x-tx);xu+=a*(p.y-ty);yu+=b*(p.y-ty);}
 const det=xx*yy-xy*xy;if(xx<.0001||yy<.0001||det<1e-9||det/(xx*yy)<.02)throw Error('홍채 이동 범위가 부족하거나 보정값이 겹칩니다. 머리를 고정하고 각 표적을 다시 바라봐 주세요.');
 const ax=(xt*yy-yt*xy)/det,bx=(yt*xx-xt*xy)/det,ay=(xu*yy-yu*xy)/det,by=(yu*xx-xu*xy)/det;
 const model={ix,iy,tx,ty,ax,bx,ay,by};model.fitMAE=points.reduce((s,p)=>{let v=project(model,p);return s+Math.hypot(v.x-p.x,v.y-p.y)},0)/9;
 if(model.fitMAE>.25)throw Error('보정 표적과 홍채 위치가 일관되지 않습니다. 보정을 다시 진행해 주세요.');return model;
}
export function project(m,p){return {x:m.tx+m.ax*(p.irisX-m.ix)+m.bx*(p.irisY-m.iy),y:m.ty+m.ay*(p.irisX-m.ix)+m.by*(p.irisY-m.iy)}}
export function direction(x,y,c=SETTINGS){const h=x<c.directionLow?'LEFT':x>c.directionHigh?'RIGHT':'',v=y<c.directionLow?'UP':y>c.directionHigh?'DOWN':'';return [v,h].filter(Boolean).join('_')||'CENTER';}
export function prediction(raw,cal,config=SETTINGS){
 const out={direction:'UNKNOWN',screen:'UNKNOWN',head:'UNKNOWN',ear:raw?.ear??null,x:null,y:null,pose:null};
 if(!raw||!cal)return out;
 if(raw.pose){out.pose=Object.fromEntries(['yaw','pitch','roll'].map(k=>[k,angleDiff(raw.pose[k],cal.neutral[k])]));const p=out.pose;out.head=Math.abs(p.yaw)>config.yaw?(p.yaw>0?'RIGHT':'LEFT'):Math.abs(p.pitch)>config.pitch?(p.pitch>0?'DOWN':'UP'):Math.abs(p.roll)>config.roll?(p.roll>0?'TILT_RIGHT':'TILT_LEFT'):'CENTER';}
 if(raw.ear<config.ear)return out;
 const p=project(cal.model,raw);if(!Number.isFinite(p.x)||!Number.isFinite(p.y))return out;
 out.x=p.x;out.y=p.y;out.direction=direction(p.x,p.y,config);out.screen=p.x>=0&&p.x<=1&&p.y>=0&&p.y<=1?'INSIDE':'OUTSIDE';return out;
}
export class Session{
 constructor(meta,config={}){this.data={schema:'gaze-validation-2',version:VERSION,meta,config:{...SETTINGS,...config},startedAt:new Date().toISOString(),duration:0,calibration:null,evaluationStart:null,samples:[],events:[],trials:[],tasks:[],timings:[],references:{a:[],b:[],consensus:[],timing:[]}};this.task=null;this.delay=null;this.calibration=null;}
 event(type,t,extra={}){const e={id:`E${this.data.events.length+1}`,type,t,...extra};this.data.events.push(e);return e;}
 setCalibration(cal,t){this.calibration=cal;this.data.calibration=cal;this.data.evaluationStart=Math.ceil(t/this.data.config.bin)*this.data.config.bin;this.event('CALIBRATION_COMPLETE',t);}
 update(raw,t){const p=prediction(raw,this.calibration,this.data.config);this.data.samples.push({t,phase:this.calibration?'validation':'calibration',face:!!raw,taskId:this.task?.id??null,itemId:this.task?.itemId??null,trialId:this.activeTrialId??null,...p,rawPose:raw?.pose??null,irisX:raw?.irisX??null,irisY:raw?.irisY??null});this.data.duration=t;return p;}
 startTask(t,info={}){if(this.task)return false;const id='T'+(this.data.tasks.length+1),itemId=String(info.itemId??id).trim(),itemLabel=String(info.itemLabel??'모의 문항 '+(this.data.tasks.length+1)).trim();if(!itemId||!itemLabel||this.data.tasks.some(k=>k.itemId===itemId))throw Error('문항 ID는 비어 있지 않고 세션 안에서 고유해야 합니다.');this.task={id,itemId,itemLabel,start:t,end:null,response:null,status:'active'};this.data.tasks.push(this.task);this.event('TASK_START',t,{taskId:id,itemId,itemLabel});return true;}
 respond(t){if(!this.task||this.task.response!==null)return false;this.task.response=t;const {id:taskId,itemId,itemLabel}=this.task;this.data.timings.push({id:taskId+'_response',taskId,itemId,itemLabel,kind:'RESPONSE',start:this.task.start,end:t,duration:t-this.task.start,basis:'manual_event'});this.event('RESPONSE',t,{taskId,itemId});return true;}
 toggleDelay(t,closeReason='manual'){if(!this.task)return false;const {id:taskId,itemId,itemLabel}=this.task;if(this.delay!==null){this.data.timings.push({id:taskId+'_delay'+(this.data.timings.length+1),taskId,itemId,itemLabel,kind:'DELAY',start:this.delay,end:t,duration:t-this.delay,autoClosed:closeReason!=='manual',closeReason,basis:'manual_event'});this.event('DELAY_END',t,{taskId,itemId,closeReason});this.delay=null;}else{this.delay=t;this.event('DELAY_START',t,{taskId,itemId});}return true;}
 endTask(t,aborted=false){if(!this.task)return;if(this.delay!==null)this.toggleDelay(t,aborted?'session_end':'task_end');this.task.end=t;this.task.status=aborted?'interrupted':'complete';this.event(aborted?'TASK_INTERRUPTED':'TASK_END',t,{taskId:this.task.id,itemId:this.task.itemId});this.task=null;}
 finish(t){this.endTask(t,true);this.data.duration=t;this.data.endedAt=new Date().toISOString();this.data.timings.push(...gazeEpisodes(this.data));return this.data;}
}
// Zero-order hold capped at 150 ms; unobserved time counts as UNKNOWN, never OUTSIDE.
export function intervals(data){const result=[];const begin=data.evaluationStart;if(begin===null)return result;const samples=data.samples.filter(s=>s.t>=begin).sort((a,b)=>a.t-b.t);let cursor=begin;for(let i=0;i<samples.length;i++){const s=samples[i],next=samples[i+1]?.t??data.duration;const end=Math.min(next,s.t+data.config.hold,data.duration);if(s.t>cursor)result.push({start:cursor,end:Math.min(s.t,data.duration),direction:'UNKNOWN',screen:'UNKNOWN',head:'UNKNOWN'});if(end>s.t)result.push({start:s.t,end,...s});cursor=Math.max(cursor,end);}if(cursor<data.duration)result.push({start:cursor,end:data.duration,direction:'UNKNOWN',screen:'UNKNOWN',head:'UNKNOWN'});return result;}
export function bins(data){const begin=data.evaluationStart;if(begin===null)return [];const spans=intervals(data),rows=[];let first=0;for(let start=begin;start+data.config.bin<=data.duration+1e-8;start+=data.config.bin){const end=start+data.config.bin,row={start:Number(start.toFixed(3)),end:Number(end.toFixed(3))};while(first<spans.length&&spans[first].end<=start)first++;for(const field of ['direction','screen','head']){const weights=new Map();let covered=0;for(let i=first;i<spans.length&&spans[i].start<end;i++){const s=spans[i],weight=Math.max(0,Math.min(end,s.end)-Math.max(start,s.start));covered+=weight;const key=s[field]??'UNKNOWN';weights.set(key,(weights.get(key)??0)+weight);}if(covered<data.config.bin-1e-7)weights.set('UNKNOWN',(weights.get('UNKNOWN')??0)+data.config.bin-covered);const sorted=[...weights].sort((a,b)=>b[1]-a[1]);row[field]=sorted.length&&(!sorted[1]||sorted[0][1]-sorted[1][1]>1e-8)?sorted[0][0]:'UNKNOWN';row[field+'Failure']=Number(((weights.get('UNKNOWN')??0)/data.config.bin).toFixed(5));}rows.push(row);}return rows;}
export function gazeEpisodes(data){const out=[];let current=null;for(const s of intervals(data)){if(s.screen!=='INSIDE'){if(current)out.push(current);current=null;}else if(current&&Math.abs(current.end-s.start)<1e-7){current.end=s.end;current.duration=current.end-current.start;}else current={id:`G${out.length+1}`,kind:'GAZE',start:s.start,end:s.end,duration:s.end-s.start};}if(current)out.push(current);return out;}
export function timeSummary(data){const values={INSIDE:0,OUTSIDE:0,UNKNOWN:0};let outsideCount=0,prev=null;for(const s of intervals(data)){values[s.screen]+=s.end-s.start;if(s.screen==='OUTSIDE'&&prev!=='OUTSIDE')outsideCount++;prev=s.screen;}return {...values,outsideCount};}
export function parseCSV(text){let rows=[],row=[],cell='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quote)throw Error('CSV 따옴표가 닫히지 않았습니다.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(!rows.length)throw Error('CSV가 비어 있습니다.');const headers=rows.shift().map(s=>s.replace(/^\ufeff/,'').trim());if(new Set(headers).size!==headers.length)throw Error('중복 CSV 열입니다.');return rows.map(r=>{if(r.length!==headers.length)throw Error('CSV 열 수가 맞지 않습니다.');return Object.fromEntries(headers.map((h,i)=>[h,r[i].trim()]));});}
export function validateReferences(rows,data,timing=false){const seen=new Set(),known=bins(data);for(const r of rows){if(r.session_id!==data.meta.session)throw Error('검증 세션 ID가 일치하지 않습니다.');if(timing){const event=data.timings.find(e=>e.id===r.id&&e.kind===r.kind);if(!event)throw Error('알 수 없는 시간 사건 ID/종류입니다.');if(seen.has(r.id))throw Error('중복 시간 사건 ID입니다.');seen.add(r.id);if(r.start_s===''||r.end_s==='')continue;const a=Number(r.start_s),b=Number(r.end_s);if(!Number.isFinite(a)||!Number.isFinite(b)||a<0||b<a||b>data.duration+.5)throw Error('기준 시간 범위를 확인해 주세요.');}else{const t=Number(r.bin_start_s);if(r.bin_start_s===''||!known.some(b=>Math.abs(b.start-t)<1e-7))throw Error('0.5초 구간 시작값이 일치하지 않습니다.');if(seen.has(t))throw Error('중복 평가 구간입니다.');seen.add(t);for(const f of ['direction','screen','head']){const allowed=f==='direction'?DIRECTIONS:f==='screen'?['INSIDE','OUTSIDE']:HEADS;if(r[f]&&!['UNCLEAR',...allowed].includes(r[f]))throw Error(`${f} 값이 올바르지 않습니다: ${r[f]}`);}}}return rows;}
export function resolvedReferences(data){const refs=data.references;return bins(data).map(bin=>{const find=arr=>arr.find(r=>Math.abs(Number(r.bin_start_s)-bin.start)<1e-7);const a=find(refs.a),b=find(refs.b),c=find(refs.consensus);let row={...bin,reference:{},disputes:[]};for(const f of ['direction','screen','head']){if(!a?.[f]||!b?.[f])row.reference[f]=null;else if(a[f]===b[f])row.reference[f]=a[f];else if(c?.[f])row.reference[f]=c[f];else{row.reference[f]=null;row.disputes.push(f);}}return row;});}
export function metrics(data){const rows=resolvedReferences(data);return ['direction','screen','head'].map(field=>{const categories=field==='direction'?DIRECTIONS:field==='screen'?['INSIDE','OUTSIDE']:HEADS;const detail=categories.map(category=>{const subset=rows.filter(r=>r.reference[field]===category);return {category,n:subset.length,correct:subset.filter(r=>r[field]===category).length,failed:subset.filter(r=>r[field]==='UNKNOWN').length,accuracy:subset.length?100*subset.filter(r=>r[field]===category).length/subset.length:null};});const tested=detail.filter(d=>d.n);return {field,detail,macro:tested.length?tested.reduce((s,d)=>s+d.accuracy,0)/tested.length:null,complete:detail.every(d=>d.n>0),unresolved:rows.filter(r=>r.disputes.includes(field)).length,unclear:rows.filter(r=>r.reference[field]==='UNCLEAR').length,missing:rows.filter(r=>r.reference[field]===null).length,failure:rows.length?100*rows.filter(r=>r[field]==='UNKNOWN').length/rows.length:null,weightedFailure:rows.length?100*rows.reduce((s,r)=>s+r[field+'Failure'],0)/rows.length:null};});}
export function timingMetrics(data){return ['GAZE','RESPONSE','DELAY'].map(kind=>{const matches=data.references.timing.filter(r=>r.kind===kind&&r.start_s!==''&&r.end_s!=='').map(r=>{const p=data.timings.find(e=>e.id===r.id&&e.kind===kind);if(!p)return null;return {id:r.id,program:p.duration,reference:Number(r.end_s)-Number(r.start_s),error:Math.abs(p.duration-(Number(r.end_s)-Number(r.start_s)))};}).filter(Boolean);return {kind,n:matches.length,mae:matches.length?matches.reduce((s,r)=>s+r.error,0)/matches.length:null,matches};});}
export function cohort(sessions){const groups=new Map();for(const s of sessions){if(s.meta.mode!=='camera'||s.meta.role!=='validation')continue;const key=s.meta.participant;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(s);}const people=[...groups].map(([participant,all])=>{const last=all.sort((a,b)=>b.startedAt.localeCompare(a.startedAt))[0];return {participant,session:last.meta.session,metrics:metrics(last),timing:timingMetrics(last)};});const stats=values=>{if(!values.length)return {n:0,mean:null,sd:null};const mean=values.reduce((a,b)=>a+b,0)/values.length;return {n:values.length,mean,sd:values.length>1?Math.sqrt(values.reduce((s,v)=>s+(v-mean)**2,0)/(values.length-1)):null};};const fields=['direction','screen','head'].map(field=>{const items=people.map(p=>p.metrics.find(m=>m.field===field));const v=stats(items.map(m=>m.macro).filter(v=>v!==null));const categories=(field==='direction'?DIRECTIONS:field==='screen'?['INSIDE','OUTSIDE']:HEADS).map(category=>({category,...stats(items.map(m=>m.detail.find(d=>d.category===category)?.accuracy).filter(v=>v!==null&&v!==undefined))}));return {field,...v,categories,minCategoryMean:categories.every(c=>c.mean!==null)?Math.min(...categories.map(c=>c.mean)):null,complete:people.length>=20&&items.every(m=>m.complete&&!m.missing&&!m.unresolved),failure:stats(items.map(m=>m.weightedFailure).filter(v=>v!==null)).mean};});const timing=['GAZE','RESPONSE','DELAY'].map(kind=>({kind,...stats(people.map(p=>p.timing.find(m=>m.kind===kind).mae).filter(v=>v!==null))}));const latest=[...groups.values()].map(all=>all.sort((a,b)=>b.startedAt.localeCompare(a.startedAt))[0]); const signatures=new Set(latest.map(s=>JSON.stringify([s.version,s.config,s.meta.device,s.meta.distanceCm,s.meta.lighting,s.meta.cameraPosition]))); return {people,fields,timing,conditionsMatch:signatures.size<=1};}
